// =============================================================================
// GENERATOR TRANSLATIONS — i18n for intelligence generators
// =============================================================================
// Generators run as hooks/services (not React components) so they can't use
// useTranslation(). This file provides a lookup-based translation system.
//
// Usage in generators:
//   import { gt } from '../generatorTranslations';
//   title: gt('overdue_invoices', ctx.language)
//   source: gt('source_billing', ctx.language)
// =============================================================================

import type { GeneratorLanguage } from './generators/types';
import { getCountryConfig, type Country, euroLeading } from '../i18n/formatting';

type TranslationMap = Record<GeneratorLanguage, string>;

// ---------------------------------------------------------------------------
// gtMoney — country-aware whole-currency formatter for generator strings.
// Replaces the legacy hardcoded `€${x.toLocaleString('nl-NL')}` anti-pattern:
// emits the right symbol + locale grouping (NL €1.234 · UK £1,234 · US $1,234)
// with 0 decimals (generators show whole euros/pounds). Defaults to NL/EUR.
// ---------------------------------------------------------------------------
export function gtMoney(amount: number, country: Country = 'NL'): string {
  const { currency, locale } = getCountryConfig(country);
  const rounded = Math.round(amount);
  try {
    return euroLeading(new Intl.NumberFormat(locale, {
      style: 'currency', currency, currencyDisplay: 'narrowSymbol',
      minimumFractionDigits: 0, maximumFractionDigits: 0,
    }).format(rounded));
  } catch {
    // narrowSymbol unsupported on some RN/Hermes Intl builds — fall back.
    return euroLeading(new Intl.NumberFormat(locale, {
      style: 'currency', currency, minimumFractionDigits: 0, maximumFractionDigits: 0,
    }).format(rounded));
  }
}

