  tip_invoice_msg: { nl: 'Facturen met een gedetailleerde omschrijving worden gemiddeld 3 dagen sneller betaald.', en: 'Invoices with a detailed description are paid about 3 days faster on average.', de: 'Rechnungen mit detaillierter Beschreibung werden im Schnitt 3 Tage schneller bezahlt.', fr: 'Les factures avec une description détaillée sont payées en moyenne 3 jours plus vite.', es: 'Las facturas con una descripción detallada se cobran de media 3 días antes.', it: 'Le fatture con una descrizione dettagliata vengono pagate in media 3 giorni prima.' },
  tip_invoice_detail: { nl: "Voeg foto's van het afgeronde werk toe aan je factuur. Klanten die het resultaat zien betalen sneller.", en: 'Add photos of the finished work to your invoice. Customers who see the result pay sooner.', de: 'Fügen Sie Ihrer Rechnung Fotos der fertigen Arbeit bei. Kunden, die das Ergebnis sehen, zahlen schneller.', fr: 'Ajoutez des photos du travail terminé à votre facture. Les clients qui voient le résultat paient plus vite.', es: 'Añade fotos del trabajo terminado a tu factura. Los clientes que ven el resultado pagan antes.', it: 'Allega alla fattura le foto del lavoro finito. I clienti che vedono il risultato pagano prima.' },
  tip_bulk_title: { nl: 'Bundel je bestellingen', en: 'Bundle your orders', de: 'Bestellungen bündeln', fr: 'Regroupez vos commandes', es: 'Agrupa tus pedidos', it: 'Raggruppa gli ordini' },
  tip_bulk_msg: { nl: 'Bestellingen bij dezelfde leverancier bundelen scheelt verzendkosten en ritten.', en: 'Bundling orders with the same supplier saves on delivery costs and trips.', de: 'Bestellungen beim selben Lieferanten zu bündeln spart Versandkosten und Fahrten.', fr: 'Regrouper les commandes chez le même fournisseur réduit les frais de livraison et les trajets.', es: 'Agrupar pedidos del mismo proveedor ahorra gastos de envío y desplazamientos.', it: 'Raggruppare gli ordini dello stesso fornitore riduce spese di spedizione e viaggi.' },
